import DashboardLayout from "@/components/DashboardLayout";
import { CommerceSettingsPanel } from "@/components/AdminCommerceSettings";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useSupabaseAuth } from "@/contexts/SupabaseAuthContext";
import { can, defaultCommercialSettings, defaultHeroSettings, isPromotionActive, roleLabels, toCsv, type CatalogCategory, type Collaborator, type CollaboratorRole, type CommercialSettings, type CustomerRequest, type HeroSettings } from "@/lib/adminCommerce";
import { fullProductCatalog, type ProductFamily } from "@/lib/site";
import { supabase } from "@/lib/supabase";
import type { SupabaseCatalogRow } from "@/lib/supabaseCatalog";
import { listProductMedia, removeProductMedia, type SupabaseMediaAsset, uploadProductMedia } from "@/lib/supabaseMedia";
import { Check, ClipboardList, Download, Eye, EyeOff, Film, ImagePlus, Loader2, Pencil, Plus, Save, Search, Settings2, Tag, Trash2, Upload, UserPlus, UsersRound, X } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useLocation, useSearch } from "wouter";
import { toast } from "sonner";

type Draft = Omit<SupabaseCatalogRow, "id">;
type RequestDraft = Omit<CustomerRequest, "id" | "created_at" | "updated_at">;

const blank: Draft = {
  slug: "", name_fr: "", name_en: "", category: "security", icon: "Fingerprint", description_fr: "", description_en: "",
  price_label: "Prix à définir", price_label_en: "Price to be set", image_url: "", gallery_urls: [], video_urls: [], status: "draft",
  availability_status: "on_request", availability_note_fr: "Disponibilité à confirmer avec notre équipe.", availability_note_en: "Availability to confirm with our team.",
  badge_fr: "", badge_en: "", search_terms_fr: [], search_terms_en: [], sort_order: 0, stock_quantity: null,
  promotion_enabled: false, promotion_price_label: "", promotion_price_label_en: "", promotion_starts_at: null, promotion_ends_at: null,
};
const blankRequest: RequestDraft = { request_type: "order", status: "new", customer_name: "", customer_phone: "", customer_email: "", product_id: null, product_name: "", quantity: 1, source: "whatsapp", internal_notes: "", assigned_to: null, created_by: null };

export function seedPayload() {
  return fullProductCatalog.map((product, index) => ({
    slug: product.id, name_fr: product.name.fr, name_en: product.name.en, category: product.family, icon: product.icon,
    description_fr: product.description.fr, description_en: product.description.en, price_label: product.price.fr, price_label_en: product.price.en,
    image_url: product.imageSrc, gallery_urls: [], video_urls: [], status: "published", availability_status: "on_request",
    availability_note_fr: "Disponibilité à confirmer avec notre équipe.", availability_note_en: "Availability to confirm with our team.",
    badge_fr: product.badge.fr, badge_en: product.badge.en, search_terms_fr: product.searchTerms.fr, search_terms_en: product.searchTerms.en, sort_order: index,
  }));
}
function asStrings(value: unknown) { return Array.isArray(value) ? value.filter((item): item is string => typeof item === "string") : []; }
function toTerms(value: string) { return value.split(",").map((part) => part.trim()).filter(Boolean); }
function datetimeLocal(value?: string | null) { return value ? new Date(value).toISOString().slice(0, 16) : ""; }
function isoOrNull(value: string) { return value ? new Date(value).toISOString() : null; }
function prettyDate(value: string) { return new Intl.DateTimeFormat("fr-FR", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)); }
function requestLabel(type: CustomerRequest["request_type"]) { return ({ order: "Commande", quote: "Devis", appointment: "Rendez-vous", question: "Question" })[type]; }
function requestStatusLabel(status: CustomerRequest["status"]) { return ({ new: "Nouvelle", contacted: "Contactée", in_discussion: "En discussion", confirmed: "Confirmée", fulfilled: "Terminée", cancelled: "Annulée" })[status]; }
export function productUsesMedia(product: Pick<SupabaseCatalogRow, "image_url" | "gallery_urls" | "video_urls">, url: string) { return [product.image_url, ...asStrings(product.gallery_urls), ...asStrings(product.video_urls)].includes(url); }

export default function AdminDashboard() {
  const { user, role } = useSupabaseAuth();
  const [location, setLocation] = useLocation();
  const search = useSearch();
  const [products, setProducts] = useState<SupabaseCatalogRow[]>([]);
  const [assets, setAssets] = useState<SupabaseMediaAsset[]>([]);
  const [requests, setRequests] = useState<CustomerRequest[]>([]);
  const [categories, setCategories] = useState<CatalogCategory[]>([]);
  const [team, setTeam] = useState<Collaborator[]>([]);
  const [commercialSettings, setCommercialSettings] = useState<CommercialSettings>(defaultCommercialSettings);
  const [heroSettings, setHeroSettings] = useState<HeroSettings>(defaultHeroSettings);
  const [loading, setLoading] = useState(true);
  const [pending, setPending] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [deletingAssetId, setDeletingAssetId] = useState<string | null>(null);
  const [editing, setEditing] = useState<string | "new" | null>(null);
  const [draft, setDraft] = useState<Draft>(blank);
  const [catalogSearch, setCatalogSearch] = useState("");
  const [catalogStatus, setCatalogStatus] = useState<"all" | Draft["status"]>("all");
  const hasOpenedNewRoute = useRef(false);
  const section = new URLSearchParams(search).get("section") || "overview";
  const canManageCatalog = can(role, "catalog_manage");

  useEffect(() => {
    if (!hasOpenedNewRoute.current && new URLSearchParams(window.location.search).get("new") === "1") {
      hasOpenedNewRoute.current = true;
      setDraft({ ...blank, sort_order: products.length });
      setEditing("new");
    }
  }, [products.length]);

  const load = useCallback(async () => {
    setLoading(true);
    const settingsRequest = supabase.from("innovtech_site_settings").select("setting_key, setting_value");
    const requestsRequest = can(role, "requests_read") ? supabase.from("innovtech_customer_requests").select("*").order("created_at", { ascending: false }) : Promise.resolve({ data: [], error: null });
    const teamRequest = can(role, "collaborators_manage") ? supabase.from("innovtech_admins").select("*").order("created_at") : Promise.resolve({ data: [], error: null });
    const [catalogue, media, requestResult, categoryResult, teamResult, settingResult] = await Promise.all([
      supabase.from("innovtech_catalog_products").select("*").order("sort_order"),
      listProductMedia().catch(() => []),
      requestsRequest,
      supabase.from("innovtech_catalog_categories").select("*").order("sort_order"),
      teamRequest,
      settingsRequest,
    ]);
    if (catalogue.error) toast.error(catalogue.error.message);
    if (requestResult.error) toast.error(requestResult.error.message);
    if (categoryResult.error) toast.error(categoryResult.error.message);
    if (teamResult.error) toast.error(teamResult.error.message);
    if (settingResult.error) toast.error(settingResult.error.message);
    setProducts((catalogue.data || []) as SupabaseCatalogRow[]);
    setAssets(media);
    setRequests((requestResult.data || []) as CustomerRequest[]);
    setCategories((categoryResult.data || []) as CatalogCategory[]);
    setTeam((teamResult.data || []) as Collaborator[]);
    const settingMap = new Map((settingResult.data || []).map((item) => [item.setting_key, item.setting_value]));
    setCommercialSettings(readSettings(settingMap.get("commerce_settings"), defaultCommercialSettings));
    setHeroSettings(readSettings(settingMap.get("home_hero"), defaultHeroSettings));
    setLoading(false);
  }, [role]);
  useEffect(() => { void load(); }, [load]);

  const set = <K extends keyof Draft>(key: K, value: Draft[K]) => setDraft((current) => ({ ...current, [key]: value }));
  const stats = useMemo(() => ({
    published: products.filter((item) => item.status === "published").length,
    drafts: products.filter((item) => item.status !== "published").length,
    lowStock: products.filter((item) => item.stock_quantity !== null && item.stock_quantity !== undefined && item.stock_quantity <= 2).length,
    promotions: products.filter((item) => isPromotionActive(item)).length,
    newRequests: requests.filter((item) => item.status === "new").length,
  }), [products, requests]);
  const filteredProducts = useMemo(() => products.filter((item) => {
    const term = catalogSearch.trim().toLowerCase();
    const matchText = !term || [item.name_fr, item.name_en, item.category, item.slug].some((value) => value.toLowerCase().includes(term));
    return matchText && (catalogStatus === "all" || item.status === catalogStatus);
  }), [catalogSearch, catalogStatus, products]);

  const openProduct = (item?: SupabaseCatalogRow) => {
    if (!canManageCatalog) { toast.error("Votre rôle permet la consultation, mais pas la modification des produits."); return; }
    if (item) { const { id: _id, ...next } = item; setDraft({ ...blank, ...next, gallery_urls: asStrings(next.gallery_urls), video_urls: asStrings(next.video_urls) }); setEditing(item.id); }
    else { setDraft({ ...blank, sort_order: products.length }); setEditing("new"); }
    if (section !== "products") setLocation("/admin?section=products");
    window.scrollTo({ top: 0, behavior: "smooth" });
  };
  async function saveProduct() {
    if (!canManageCatalog) return;
    if (!draft.slug.trim() || !draft.name_fr.trim() || !draft.name_en.trim()) { toast.error("Le nom français, le nom anglais et l’URL produit sont requis."); return; }
    if (!draft.image_url.trim()) { toast.error("Ajoutez une image principale au produit."); return; }
    if (draft.promotion_enabled && !draft.promotion_price_label?.trim()) { toast.error("Saisissez un prix promotionnel ou désactivez la promotion."); return; }
    setPending(true);
    const payload = { ...draft, slug: draft.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""), gallery_urls: asStrings(draft.gallery_urls), video_urls: asStrings(draft.video_urls) };
    const request = editing === "new" ? supabase.from("innovtech_catalog_products").insert(payload) : supabase.from("innovtech_catalog_products").update(payload).eq("id", editing as string);
    const { error } = await request;
    setPending(false);
    if (error) { toast.error(error.message); return; }
    toast.success(editing === "new" ? "Produit ajouté au catalogue." : "Produit mis à jour.");
    setEditing(null); setDraft(blank); await load();
  }
  async function toggleVisibility(item: SupabaseCatalogRow) {
    if (!canManageCatalog) return;
    const status = item.status === "published" ? "hidden" : "published";
    const { error } = await supabase.from("innovtech_catalog_products").update({ status }).eq("id", item.id);
    if (error) toast.error(error.message); else { toast.success(status === "published" ? "Produit publié." : "Produit masqué."); await load(); }
  }
  async function upload(file: File) {
    if (!user || !can(role, "media_manage")) throw new Error("Votre rôle ne permet pas de gérer les médias.");
    setUploading(true);
    try { const asset = await uploadProductMedia(file, draft.name_fr || file.name, user.id); setAssets((current) => [asset, ...current]); toast.success("Média ajouté. Sélectionnez-le pour le produit."); return asset; }
    finally { setUploading(false); }
  }
  async function deleteUnusedAsset(asset: SupabaseMediaAsset) {
    if (!can(role, "media_manage")) return;
    if (products.some((product) => productUsesMedia(product, asset.public_url))) { toast.error("Ce média est encore associé à un produit. Retirez-le de la fiche avant de le supprimer."); return; }
    if (!window.confirm(`Supprimer définitivement « ${asset.title} » de la bibliothèque ? Cette action retire le fichier du stockage.`)) return;
    setDeletingAssetId(asset.id);
    try { await removeProductMedia(asset); setAssets((current) => current.filter((item) => item.id !== asset.id)); toast.success("Média supprimé définitivement."); }
    catch (error) { toast.error(error instanceof Error ? error.message : "La suppression du média a échoué."); }
    finally { setDeletingAssetId(null); }
  }
  const saveSettings = async () => {
    if (!can(role, "settings_manage")) return;
    setPending(true);
    const { error } = await supabase.from("innovtech_site_settings").upsert([
      { setting_key: "commerce_settings", setting_value: JSON.stringify(commercialSettings) },
      { setting_key: "home_hero", setting_value: JSON.stringify(heroSettings) },
    ]);
    setPending(false);
    if (error) toast.error(error.message); else { toast.success("Réglages enregistrés. Le site public se mettra à jour automatiquement."); await load(); }
  };
  const exportData = (kind: "products" | "requests") => {
    if (!can(role, "export_manage")) return;
    const csv = kind === "products"
      ? toCsv(["Nom FR", "Nom EN", "URL", "Catégorie", "Prix FR", "Prix promo FR", "Statut", "Disponibilité", "Stock"], products.map((item) => [item.name_fr, item.name_en, item.slug, item.category, item.price_label, item.promotion_price_label || "", item.status, item.availability_status, item.stock_quantity ?? ""]))
      : toCsv(["Date", "Type", "Statut", "Client", "Téléphone", "E-mail", "Produit", "Quantité", "Source", "Notes"], requests.map((item) => [item.created_at, requestLabel(item.request_type), requestStatusLabel(item.status), item.customer_name, item.customer_phone, item.customer_email, item.product_name, item.quantity, item.source, item.internal_notes]));
    const url = URL.createObjectURL(new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8" }));
    const link = document.createElement("a"); link.href = url; link.download = `innovtech-${kind}-${new Date().toISOString().slice(0, 10)}.csv`; link.click(); URL.revokeObjectURL(url);
  };

  return <DashboardLayout><section className="mx-auto max-w-7xl pb-12">
    <header className="overflow-hidden rounded-[2rem] bg-[#081A3C] p-6 text-white shadow-[0_24px_70px_rgba(8,26,60,.22)] sm:p-10"><p className="text-xs font-extrabold uppercase tracking-[0.16em] text-cyan-300">InnovTech Commerce · {role ? roleLabels[role] : "Accès sécurisé"}</p><div className="mt-3 flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="font-display text-3xl font-bold tracking-[-0.055em] sm:text-5xl">{section === "overview" ? "Votre activité, au même endroit." : section === "products" ? "Produits et promotions." : section === "requests" ? "Demandes commerciales." : section === "categories" ? "Catégories de boutique." : section === "team" ? "Votre équipe." : "Réglages de diffusion."}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-blue-100/80">Les actions autorisées par votre rôle sont synchronisées avec la boutique publique, sans modifier le code du site.</p></div>{canManageCatalog && <Button size="lg" className="bg-[#1FAF62] text-white hover:bg-[#168b4c]" onClick={() => openProduct()}><Plus className="mr-2 h-4 w-4" />Nouveau produit</Button>}</div></header>
    {loading ? <div className="grid min-h-64 place-items-center"><Loader2 className="h-8 w-8 animate-spin text-blue-700" /></div> : <>
      {section === "overview" && <Overview stats={stats} requests={requests} canExport={can(role, "export_manage")} onExport={exportData} onOpenProducts={() => setLocation("/admin?section=products")} onOpenRequests={() => setLocation("/admin?section=requests")} />}
      {section === "products" && <ProductsPanel products={filteredProducts} categories={categories} search={catalogSearch} status={catalogStatus} onSearch={setCatalogSearch} onStatus={setCatalogStatus} canManage={canManageCatalog} onNew={() => openProduct()} onEdit={openProduct} onToggle={(item) => void toggleVisibility(item)} />}
      {section === "requests" && can(role, "requests_read") && <RequestsPanel requests={requests} products={products} team={team} userId={user?.id || null} canManage={can(role, "requests_manage")} onRefresh={load} />}
      {section === "categories" && can(role, "categories_manage") && <CategoriesPanel categories={categories} onRefresh={load} />}
      {section === "team" && can(role, "collaborators_manage") && <TeamPanel team={team} currentUserId={user?.id || ""} onRefresh={load} />}
      {section === "settings" && can(role, "settings_manage") && <CommerceSettingsPanel commercial={commercialSettings} hero={heroSettings} assets={assets} onCommercialChange={setCommercialSettings} onHeroChange={setHeroSettings} pending={pending} onSave={() => void saveSettings()} />}
      {!["overview", "products", "requests", "categories", "team", "settings"].includes(section) && <EmptyPanel />}
    </>}
    {editing && <ProductEditor draft={draft} set={set} assets={assets} categories={categories} pending={pending} uploading={uploading} deletingAssetId={deletingAssetId} canManageMedia={can(role, "media_manage")} onCancel={() => { setEditing(null); setDraft(blank); }} onSave={() => void saveProduct()} onUpload={upload} onDeleteAsset={(asset) => void deleteUnusedAsset(asset)} />}
  </section></DashboardLayout>;
}

function readSettings<T>(value: string | undefined, fallback: T) { try { return value ? { ...fallback, ...JSON.parse(value) as Partial<T> } : fallback; } catch { return fallback; } }
function Stat({ value, label, tone = "blue" }: { value: number; label: string; tone?: "blue" | "green" | "amber" }) { const colors = { blue: "border-blue-100 bg-white", green: "border-green-100 bg-green-50/50", amber: "border-amber-100 bg-amber-50/60" }; return <article className={`rounded-2xl border px-5 py-4 shadow-sm ${colors[tone]}`}><p className="text-2xl font-extrabold text-[#081A3C]">{value}</p><p className="text-xs font-bold uppercase tracking-[.1em] text-slate-500">{label}</p></article>; }
function EmptyPanel() { return <article className="mt-8 rounded-3xl border border-blue-100 bg-white p-8 text-center shadow-sm"><h2 className="font-display text-2xl font-bold text-[#081A3C]">Module indisponible</h2><p className="mt-2 text-sm text-slate-600">Utilisez la navigation pour revenir vers un module auquel votre rôle donne accès.</p></article>; }

function Overview({ stats, requests, canExport, onExport, onOpenProducts, onOpenRequests }: { stats: { published: number; drafts: number; lowStock: number; promotions: number; newRequests: number }; requests: CustomerRequest[]; canExport: boolean; onExport: (kind: "products" | "requests") => void; onOpenProducts: () => void; onOpenRequests: () => void }) {
  return <div className="mt-6 grid gap-6"><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Stat value={stats.published} label="Produits en ligne" tone="green" /><Stat value={stats.drafts} label="Brouillons / masqués" /><Stat value={stats.promotions} label="Promotions actives" tone="amber" /><Stat value={stats.lowStock} label="Stock à suivre" tone="amber" /><Stat value={stats.newRequests} label="Nouvelles demandes" tone="blue" /></section><section className="grid gap-5 lg:grid-cols-[1fr_.8fr]"><article className="rounded-3xl border border-blue-100 bg-white p-5 shadow-sm sm:p-7"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="eyebrow">Actions rapides</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#081A3C]">Gardez la boutique à jour.</h2></div><Button variant="outline" onClick={onOpenProducts}>Voir les produits</Button></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><button type="button" onClick={onOpenProducts} className="rounded-2xl bg-[#F4F8FF] p-5 text-left transition hover:bg-blue-50"><Tag className="h-5 w-5 text-blue-700" /><strong className="mt-4 block text-base text-[#081A3C]">Gérer prix et promotions</strong><span className="mt-1 block text-sm text-slate-600">Modifiez le prix affiché, le prix promotionnel, le stock et la visibilité.</span></button><button type="button" onClick={onOpenRequests} className="rounded-2xl bg-[#ECFAF2] p-5 text-left transition hover:bg-green-50"><ClipboardList className="h-5 w-5 text-green-700" /><strong className="mt-4 block text-base text-[#081A3C]">Suivre WhatsApp</strong><span className="mt-1 block text-sm text-slate-600">Enregistrez vos commandes, devis, rendez-vous et leurs prochaines étapes.</span></button></div></article><article className="rounded-3xl bg-[#081A3C] p-5 text-white shadow-[0_18px_44px_rgba(8,26,60,.18)] sm:p-7"><p className="text-xs font-extrabold uppercase tracking-[.16em] text-cyan-300">Dernières demandes</p><div className="mt-5 grid gap-3">{requests.slice(0, 3).map((item) => <div key={item.id} className="rounded-xl border border-white/10 bg-white/10 p-3"><div className="flex justify-between gap-3"><strong className="text-sm">{item.customer_name || "Client non renseigné"}</strong><span className="text-xs font-bold text-cyan-200">{requestStatusLabel(item.status)}</span></div><p className="mt-1 text-xs text-blue-100/75">{requestLabel(item.request_type)} · {item.product_name || "Demande générale"}</p></div>)}{requests.length === 0 && <p className="rounded-xl border border-dashed border-white/20 p-4 text-sm text-blue-100/70">Aucune demande enregistrée pour l’instant. Ajoutez-les depuis le module Demandes après vos échanges WhatsApp.</p>}</div>{canExport && <div className="mt-6 grid gap-2 sm:grid-cols-2"><Button variant="outline" className="border-white/20 bg-white/10 text-white hover:bg-white/20 hover:text-white" onClick={() => onExport("products")}><Download className="mr-2 h-4 w-4" />Exporter produits</Button><Button variant="outline" className="border-white/20 bg-white/10 text-white hover:bg-white/20 hover:text-white" onClick={() => onExport("requests")}><Download className="mr-2 h-4 w-4" />Exporter demandes</Button></div>}</article></section></div>;
}

function ProductsPanel({ products, categories, search, status, onSearch, onStatus, canManage, onNew, onEdit, onToggle }: { products: SupabaseCatalogRow[]; categories: CatalogCategory[]; search: string; status: "all" | Draft["status"]; onSearch: (value: string) => void; onStatus: (value: "all" | Draft["status"]) => void; canManage: boolean; onNew: () => void; onEdit: (product: SupabaseCatalogRow) => void; onToggle: (product: SupabaseCatalogRow) => void }) {
  const categoryName = (slug: string) => categories.find((category) => category.slug === slug)?.name_fr || slug;
  return <section className="mt-8"><div className="flex flex-col gap-4 xl:flex-row xl:items-end xl:justify-between"><div><p className="eyebrow">Catalogue</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#081A3C]">Produits, stock et promotions</h2></div>{canManage && <Button onClick={onNew}><Plus className="mr-2 h-4 w-4" />Ajouter un produit</Button>}</div><div className="mt-5 grid gap-3 rounded-2xl border border-blue-100 bg-white p-3 shadow-sm sm:grid-cols-[1fr_auto]"><label className="relative block"><Search className="pointer-events-none absolute left-3 top-3.5 h-4 w-4 text-slate-400" /><Input className="pl-9" value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Rechercher un produit, une catégorie ou une URL…" /></label><select aria-label="Filtrer les produits par statut" className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-bold text-slate-700" value={status} onChange={(event) => onStatus(event.target.value as "all" | Draft["status"])}><option value="all">Tous les statuts</option><option value="published">En ligne</option><option value="draft">Brouillons</option><option value="hidden">Masqués</option></select></div><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{products.map((item) => <article key={item.id} className="overflow-hidden rounded-3xl border border-slate-100 bg-white shadow-[0_12px_32px_rgba(20,68,145,.08)]"><img src={item.image_url} alt="" className="aspect-[16/10] w-full bg-slate-100 object-cover" /><div className="p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[.12em] text-blue-700">{item.status === "published" ? "En ligne" : item.status === "draft" ? "Brouillon" : "Masqué"} · {categoryName(item.category)}</p><h3 className="mt-1 font-display text-xl font-bold text-[#081A3C]">{item.name_fr}</h3></div><span className="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700">{item.price_label}</span></div>{isPromotionActive(item) && <p className="mt-3 inline-flex rounded-full bg-amber-100 px-2.5 py-1 text-xs font-extrabold text-amber-800">Promo : {item.promotion_price_label}</p>}<p className="mt-3 line-clamp-2 text-sm leading-6 text-slate-600">{item.description_fr}</p><div className="mt-4 flex flex-wrap gap-2 text-xs font-bold text-slate-500"><span className="rounded-lg bg-slate-100 px-2 py-1">{item.availability_status === "available" ? "Disponible" : item.availability_status === "on_request" ? "Sur commande" : "Indisponible"}</span>{item.stock_quantity !== null && item.stock_quantity !== undefined && <span className="rounded-lg bg-slate-100 px-2 py-1">Stock : {item.stock_quantity}</span>}</div>{canManage && <div className="mt-5 grid grid-cols-2 gap-2"><Button variant="outline" onClick={() => onEdit(item)}><Pencil className="mr-2 h-4 w-4" />Modifier</Button><Button variant="outline" onClick={() => onToggle(item)}>{item.status === "published" ? <EyeOff className="mr-2 h-4 w-4" /> : <Eye className="mr-2 h-4 w-4" />}{item.status === "published" ? "Masquer" : "Publier"}</Button></div>}</div></article>)}{products.length === 0 && <div className="rounded-3xl border border-dashed border-blue-200 bg-white p-8 text-center text-sm text-slate-600 sm:col-span-2 xl:col-span-3">Aucun produit ne correspond à ce filtre.</div>}</div></section>;
}

function ProductEditor({ draft, set, assets, categories, pending, uploading, deletingAssetId, canManageMedia, onCancel, onSave, onUpload, onDeleteAsset }: { draft: Draft; set: <K extends keyof Draft>(key: K, value: Draft[K]) => void; assets: SupabaseMediaAsset[]; categories: CatalogCategory[]; pending: boolean; uploading: boolean; deletingAssetId: string | null; canManageMedia: boolean; onCancel: () => void; onSave: () => void; onUpload: (file: File) => Promise<SupabaseMediaAsset>; onDeleteAsset: (asset: SupabaseMediaAsset) => void }) {
  const images = asStrings(draft.gallery_urls); const videos = asStrings(draft.video_urls);
  const addAsset = (asset: SupabaseMediaAsset) => { if (asset.media_type === "image") set("gallery_urls", Array.from(new Set([...images, asset.public_url]))); else set("video_urls", Array.from(new Set([...videos, asset.public_url]))); };
  const removeAsset = (url: string, kind: "gallery_urls" | "video_urls") => set(kind, asStrings(draft[kind]).filter((item) => item !== url));
  const chooseFile = async (file?: File) => { if (!file) return; try { const asset = await onUpload(file); addAsset(asset); if (asset.media_type === "image" && !draft.image_url) set("image_url", asset.public_url); } catch (error) { toast.error(error instanceof Error ? error.message : "L’envoi a échoué."); } };
  return <section className="mt-8 rounded-[2rem] border border-blue-100 bg-white p-5 shadow-[0_18px_45px_rgba(20,68,145,.1)] sm:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">Éditeur e-commerce</p><h2 className="mt-2 font-display text-3xl font-bold tracking-[-.05em] text-[#081A3C]">{draft.slug ? "Modifier le produit" : "Ajouter un produit"}</h2><p className="mt-2 text-sm leading-6 text-slate-600">Les prix, photos, vidéos, disponibilité et promotion sont synchronisés vers la boutique publique après publication.</p></div><Button variant="ghost" onClick={onCancel}>Fermer</Button></div><div className="mt-7 grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><div className="grid gap-4 sm:grid-cols-2"><Field label="Nom français *" value={draft.name_fr} onChange={(value) => set("name_fr", value)} placeholder="Ex. Casque Bluetooth" /><Field label="Nom anglais *" value={draft.name_en} onChange={(value) => set("name_en", value)} placeholder="Ex. Bluetooth headset" /><Field label="URL du produit *" value={draft.slug} onChange={(value) => set("slug", value)} placeholder="casque-bluetooth" /><label className="grid gap-2 text-sm font-bold text-slate-700">Catégorie<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.category} onChange={(event) => set("category", event.target.value as ProductFamily)}>{categories.filter((category) => category.active || category.slug === draft.category).map((category) => <option key={category.id} value={category.slug}>{category.name_fr}</option>)}</select></label><Field label="Prix français" value={draft.price_label} onChange={(value) => set("price_label", value)} placeholder="Ex. 25 000 FCFA" /><Field label="Prix anglais" value={draft.price_label_en || ""} onChange={(value) => set("price_label_en", value)} placeholder="Ex. 25,000 XAF" /><label className="grid gap-2 text-sm font-bold text-slate-700">Disponibilité<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.availability_status} onChange={(event) => set("availability_status", event.target.value)}><option value="available">Disponible</option><option value="on_request">Sur commande</option><option value="unavailable">Indisponible</option></select></label><label className="grid gap-2 text-sm font-bold text-slate-700">Quantité en stock (facultatif)<Input type="number" min="0" value={draft.stock_quantity ?? ""} onChange={(event) => set("stock_quantity", event.target.value === "" ? null : Math.max(0, Number(event.target.value)))} placeholder="Ex. 8" /></label><label className="grid gap-2 text-sm font-bold text-slate-700 sm:col-span-2">Description française *<Textarea rows={4} value={draft.description_fr} onChange={(event) => set("description_fr", event.target.value)} placeholder="Décrivez clairement le produit…" /></label><label className="grid gap-2 text-sm font-bold text-slate-700 sm:col-span-2">Description anglaise *<Textarea rows={4} value={draft.description_en} onChange={(event) => set("description_en", event.target.value)} placeholder="Describe the product clearly…" /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Visibilité<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.status} onChange={(event) => set("status", event.target.value as Draft["status"])}><option value="published">Publié — visible dans la boutique</option><option value="draft">Brouillon — privé</option><option value="hidden">Masqué — privé</option></select></label><Field label="Mots-clés de recherche FR" value={asStrings(draft.search_terms_fr).join(", ")} onChange={(value) => set("search_terms_fr", toTerms(value))} placeholder="casque, audio, bluetooth" /><label className="sm:col-span-2 flex items-center gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm font-bold text-amber-900"><input type="checkbox" className="h-4 w-4 accent-amber-600" checked={Boolean(draft.promotion_enabled)} onChange={(event) => set("promotion_enabled", event.target.checked)} />Activer une promotion pour ce produit</label>{draft.promotion_enabled && <><Field label="Prix promotionnel FR *" value={draft.promotion_price_label || ""} onChange={(value) => set("promotion_price_label", value)} placeholder="Ex. 20 000 FCFA" /><Field label="Prix promotionnel EN" value={draft.promotion_price_label_en || ""} onChange={(value) => set("promotion_price_label_en", value)} placeholder="Ex. 20,000 XAF" /><label className="grid gap-2 text-sm font-bold text-slate-700">Début de la promotion<Input type="datetime-local" value={datetimeLocal(draft.promotion_starts_at)} onChange={(event) => set("promotion_starts_at", isoOrNull(event.target.value))} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Fin de la promotion<Input type="datetime-local" value={datetimeLocal(draft.promotion_ends_at)} onChange={(event) => set("promotion_ends_at", isoOrNull(event.target.value))} /></label></>}</div><MediaPanel title="Photos du produit" kind="image" urls={images} primaryUrl={draft.image_url} assets={assets} uploading={uploading} deletingAssetId={deletingAssetId} canManage={canManageMedia} onChooseFile={chooseFile} onAdd={addAsset} onRemove={(url) => removeAsset(url, "gallery_urls")} onPrimary={(url) => set("image_url", url)} onDeleteAsset={onDeleteAsset} /><MediaPanel title="Vidéos du produit" kind="video" urls={videos} assets={assets} uploading={uploading} deletingAssetId={deletingAssetId} canManage={canManageMedia} onChooseFile={chooseFile} onAdd={addAsset} onRemove={(url) => removeAsset(url, "video_urls")} onDeleteAsset={onDeleteAsset} /></div><div className="mt-7 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><Button variant="outline" onClick={onCancel}>Annuler</Button><Button className="bg-blue-700 px-7 hover:bg-blue-800" disabled={pending} onClick={onSave}>{pending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}Enregistrer le produit</Button></div></section>;
}

function MediaPanel({ title, kind, urls, primaryUrl, assets, uploading, deletingAssetId, canManage, onChooseFile, onAdd, onRemove, onPrimary, onDeleteAsset }: { title: string; kind: "image" | "video"; urls: string[]; primaryUrl?: string; assets: SupabaseMediaAsset[]; uploading: boolean; deletingAssetId: string | null; canManage: boolean; onChooseFile: (file?: File) => void; onAdd: (asset: SupabaseMediaAsset) => void; onRemove: (url: string) => void; onPrimary?: (url: string) => void; onDeleteAsset: (asset: SupabaseMediaAsset) => void }) { const Icon = kind === "image" ? ImagePlus : Film; const available = assets.filter((asset) => asset.media_type === kind && !urls.includes(asset.public_url)); return <div className="rounded-2xl bg-[#F4F8FF] p-4 sm:p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-extrabold text-[#081A3C]">{title}</p><p className="mt-1 text-xs leading-5 text-slate-500">Ajoutez un fichier ou choisissez dans vos médias.</p></div><Icon className="h-5 w-5 text-blue-700" /></div>{canManage && <label className="mt-4 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-blue-300 bg-white px-4 py-3 text-sm font-bold text-blue-700 transition hover:bg-blue-50"><Upload className="h-4 w-4" />{uploading ? "Envoi en cours…" : `Ajouter une ${kind === "image" ? "photo" : "vidéo"}`}<input className="sr-only" type="file" accept={kind === "image" ? "image/jpeg,image/png,image/webp" : "video/mp4,video/webm"} disabled={uploading} onChange={(event) => { onChooseFile(event.target.files?.[0]); event.currentTarget.value = ""; }} /></label>}{urls.length > 0 && <div className="mt-4 grid grid-cols-2 gap-3">{urls.map((url) => <article key={url} className="group relative overflow-hidden rounded-xl bg-slate-900">{kind === "image" ? <img src={url} alt="Média du produit" className="aspect-square w-full object-cover" /> : <video src={url} className="aspect-square w-full object-cover" controls preload="metadata" />}{canManage && <button type="button" className="absolute right-2 top-2 grid h-7 w-7 place-items-center rounded-full bg-slate-950/75 text-white" onClick={() => onRemove(url)} aria-label="Retirer ce média"><X className="h-4 w-4" /></button>}{kind === "image" && canManage && <Button type="button" size="sm" className="absolute bottom-2 left-2 h-8 bg-white text-xs text-[#081A3C] hover:bg-white" onClick={() => onPrimary?.(url)}>{primaryUrl === url ? <><Check className="mr-1 h-3.5 w-3.5" />Principale</> : "Définir principale"}</Button>}</article>)}</div>}{canManage && available.length > 0 && <div className="mt-4"><p className="text-xs font-bold uppercase tracking-[.1em] text-slate-500">Médias non utilisés</p><p className="mt-1 text-xs leading-5 text-slate-500">Ajoutez-les au produit ou supprimez-les définitivement du stockage.</p><div className="mt-2 flex gap-2 overflow-x-auto pb-1">{available.map((asset) => <div key={asset.id} className="relative h-14 w-14 shrink-0"><button type="button" onClick={() => onAdd(asset)} className="h-full w-full overflow-hidden rounded-lg border-2 border-transparent bg-white ring-offset-2 hover:border-blue-500 focus:border-blue-600">{kind === "image" ? <img src={asset.public_url} alt={asset.title} className="h-full w-full object-cover" /> : <Film className="m-auto h-5 w-5 text-blue-700" />}<span className="sr-only">Ajouter {asset.title}</span></button><button type="button" className="absolute -right-1 -top-1 grid h-5 w-5 place-items-center rounded-full bg-red-600 text-white shadow-sm hover:bg-red-700 disabled:opacity-50" disabled={deletingAssetId === asset.id} onClick={() => onDeleteAsset(asset)} aria-label={`Supprimer définitivement ${asset.title}`}><Trash2 className="h-3 w-3" /></button></div>)}</div></div>}</div>; }

function RequestsPanel({ requests, products, team, userId, canManage, onRefresh }: { requests: CustomerRequest[]; products: SupabaseCatalogRow[]; team: Collaborator[]; userId: string | null; canManage: boolean; onRefresh: () => Promise<void> }) {
  const [adding, setAdding] = useState(false); const [draft, setDraft] = useState<RequestDraft>(blankRequest); const [saving, setSaving] = useState<string | null>(null);
  const create = async () => { if (!canManage || !userId) return; setSaving("new"); const { error } = await supabase.from("innovtech_customer_requests").insert({ ...draft, created_by: userId, product_name: draft.product_name || products.find((product) => product.id === draft.product_id)?.name_fr || "" }); setSaving(null); if (error) toast.error(error.message); else { toast.success("Demande ajoutée."); setDraft(blankRequest); setAdding(false); await onRefresh(); } };
  const save = async (item: CustomerRequest, changes: Partial<CustomerRequest>) => { if (!canManage) return; setSaving(item.id); const { error } = await supabase.from("innovtech_customer_requests").update(changes).eq("id", item.id); setSaving(null); if (error) toast.error(error.message); else { toast.success("Suivi mis à jour."); await onRefresh(); } };
  return <section className="mt-8"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">WhatsApp et suivi</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#081A3C]">Demandes commerciales</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">Ajoutez une commande, un devis ou un rendez-vous après l’échange WhatsApp. Aucun client n’est créé automatiquement.</p></div>{canManage && <Button onClick={() => setAdding((value) => !value)}><Plus className="mr-2 h-4 w-4" />Nouvelle demande</Button>}</div>{adding && <article className="mt-5 rounded-3xl border border-blue-100 bg-white p-5 shadow-sm sm:p-7"><h3 className="font-display text-xl font-bold text-[#081A3C]">Ajouter une demande</h3><RequestForm draft={draft} products={products} team={team} onChange={setDraft} /><div className="mt-5 flex justify-end gap-3"><Button variant="outline" onClick={() => setAdding(false)}>Annuler</Button><Button disabled={saving === "new"} onClick={() => void create()}>{saving === "new" && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Enregistrer</Button></div></article>}<div className="mt-5 grid gap-4">{requests.map((item) => <article key={item.id} className="rounded-3xl border border-slate-100 bg-white p-5 shadow-sm"><div className="flex flex-col justify-between gap-4 lg:flex-row"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-extrabold text-blue-700">{requestLabel(item.request_type)}</span><span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-extrabold text-slate-600">{requestStatusLabel(item.status)}</span><span className="text-xs font-semibold text-slate-400">{prettyDate(item.created_at)}</span></div><h3 className="mt-3 font-display text-xl font-bold text-[#081A3C]">{item.customer_name || "Client non renseigné"}</h3><p className="mt-1 text-sm text-slate-600">{[item.customer_phone, item.customer_email].filter(Boolean).join(" · ") || "Coordonnées à compléter"}</p><p className="mt-3 text-sm font-bold text-slate-700">{item.product_name || "Demande générale"} · Qté {item.quantity}</p>{item.internal_notes && <p className="mt-2 text-sm leading-6 text-slate-500">{item.internal_notes}</p>}</div>{canManage && <div className="grid gap-2 sm:grid-cols-2 lg:w-72 lg:grid-cols-1"><label className="sr-only" htmlFor={`request-status-${item.id}`}>Statut</label><select id={`request-status-${item.id}`} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-bold text-slate-700" value={item.status} onChange={(event) => void save(item, { status: event.target.value as CustomerRequest["status"] })}><option value="new">Nouvelle</option><option value="contacted">Contactée</option><option value="in_discussion">En discussion</option><option value="confirmed">Confirmée</option><option value="fulfilled">Terminée</option><option value="cancelled">Annulée</option></select><label className="sr-only" htmlFor={`request-assigned-${item.id}`}>Attribuée à</label><select id={`request-assigned-${item.id}`} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-bold text-slate-700" value={item.assigned_to || ""} onChange={(event) => void save(item, { assigned_to: event.target.value || null })}><option value="">Non attribuée</option>{team.filter((member) => member.active).map((member) => <option key={member.user_id} value={member.user_id}>{member.display_name || member.email}</option>)}</select></div>}</div>{saving === item.id && <p className="mt-3 flex items-center gap-2 text-xs font-bold text-blue-700"><Loader2 className="h-3.5 w-3.5 animate-spin" />Mise à jour…</p>}</article>)}{requests.length === 0 && <div className="rounded-3xl border border-dashed border-blue-200 bg-white p-10 text-center text-sm text-slate-600">Aucune demande enregistrée. Utilisez « Nouvelle demande » après une conversation WhatsApp.</div>}</div></section>;
}
function RequestForm({ draft, products, team, onChange }: { draft: RequestDraft; products: SupabaseCatalogRow[]; team: Collaborator[]; onChange: (value: RequestDraft) => void }) { const set = <K extends keyof RequestDraft>(key: K, value: RequestDraft[K]) => onChange({ ...draft, [key]: value }); return <div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="grid gap-2 text-sm font-bold text-slate-700">Type<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.request_type} onChange={(event) => set("request_type", event.target.value as RequestDraft["request_type"])}><option value="order">Commande</option><option value="quote">Devis</option><option value="appointment">Rendez-vous</option><option value="question">Question</option></select></label><label className="grid gap-2 text-sm font-bold text-slate-700">Source<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.source} onChange={(event) => set("source", event.target.value as RequestDraft["source"])}><option value="whatsapp">WhatsApp</option><option value="website">Site web</option><option value="manual">Ajout manuel</option></select></label><Field label="Nom du client" value={draft.customer_name} onChange={(value) => set("customer_name", value)} /><Field label="Téléphone" value={draft.customer_phone} onChange={(value) => set("customer_phone", value)} placeholder="Ex. +237…" /><Field label="E-mail (facultatif)" value={draft.customer_email} onChange={(value) => set("customer_email", value)} /><label className="grid gap-2 text-sm font-bold text-slate-700">Produit<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.product_id || ""} onChange={(event) => set("product_id", event.target.value || null)}><option value="">Demande générale</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name_fr}</option>)}</select></label><label className="grid gap-2 text-sm font-bold text-slate-700">Quantité<Input type="number" min="1" value={draft.quantity} onChange={(event) => set("quantity", Math.max(1, Number(event.target.value)))} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Attribuer à<select className="h-11 rounded-xl border border-slate-200 bg-white px-3" value={draft.assigned_to || ""} onChange={(event) => set("assigned_to", event.target.value || null)}><option value="">Non attribuée</option>{team.filter((member) => member.active).map((member) => <option key={member.user_id} value={member.user_id}>{member.display_name || member.email}</option>)}</select></label><label className="grid gap-2 text-sm font-bold text-slate-700 sm:col-span-2">Notes internes<Textarea rows={3} value={draft.internal_notes} onChange={(event) => set("internal_notes", event.target.value)} placeholder="Contexte de l’échange, prochaines étapes, disponibilité…" /></label></div>; }

function CategoriesPanel({ categories, onRefresh }: { categories: CatalogCategory[]; onRefresh: () => Promise<void> }) { const [adding, setAdding] = useState(false); const [newCategory, setNewCategory] = useState({ slug: "", name_fr: "", name_en: "" }); const [saving, setSaving] = useState<string | null>(null); const save = async (category: CatalogCategory, changes: Partial<CatalogCategory>) => { setSaving(category.id); const { error } = await supabase.from("innovtech_catalog_categories").update(changes).eq("id", category.id); setSaving(null); if (error) toast.error(error.message); else { toast.success("Catégorie mise à jour."); await onRefresh(); } }; const create = async () => { const slug = newCategory.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, ""); if (!slug || !newCategory.name_fr.trim() || !newCategory.name_en.trim()) { toast.error("Le nom français, le nom anglais et l’URL sont requis."); return; } setSaving("new"); const { error } = await supabase.from("innovtech_catalog_categories").insert({ ...newCategory, slug, sort_order: categories.length, active: true }); setSaving(null); if (error) toast.error(error.message); else { toast.success("Catégorie ajoutée."); setNewCategory({ slug: "", name_fr: "", name_en: "" }); setAdding(false); await onRefresh(); } }; return <section className="mt-8"><div className="flex flex-wrap items-end justify-between gap-4"><div><p className="eyebrow">Organisation</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#081A3C]">Catégories de boutique</h2><p className="mt-2 text-sm text-slate-600">Renommez, ordonnez ou masquez les catégories sans modifier le code.</p></div><Button onClick={() => setAdding((value) => !value)}><Plus className="mr-2 h-4 w-4" />Nouvelle catégorie</Button></div>{adding && <article className="mt-5 rounded-3xl border border-blue-100 bg-white p-5 shadow-sm"><div className="grid gap-3 sm:grid-cols-3"><Field label="Nom français" value={newCategory.name_fr} onChange={(value) => setNewCategory({ ...newCategory, name_fr: value })} /><Field label="Nom anglais" value={newCategory.name_en} onChange={(value) => setNewCategory({ ...newCategory, name_en: value })} /><Field label="URL catégorie" value={newCategory.slug} onChange={(value) => setNewCategory({ ...newCategory, slug: value })} placeholder="ex. accessoires" /></div><div className="mt-4 flex justify-end gap-3"><Button variant="outline" onClick={() => setAdding(false)}>Annuler</Button><Button disabled={saving === "new"} onClick={() => void create()}>Créer la catégorie</Button></div></article>}<div className="mt-5 grid gap-3">{categories.map((category) => <article key={category.id} className="grid gap-3 rounded-2xl border border-slate-100 bg-white p-4 shadow-sm lg:grid-cols-[1fr_1fr_130px_auto_auto]"><Input aria-label={`Nom français ${category.name_fr}`} defaultValue={category.name_fr} onBlur={(event) => event.target.value !== category.name_fr && void save(category, { name_fr: event.target.value })} /><Input aria-label={`Nom anglais ${category.name_fr}`} defaultValue={category.name_en} onBlur={(event) => event.target.value !== category.name_en && void save(category, { name_en: event.target.value })} /><Input aria-label={`Ordre ${category.name_fr}`} type="number" defaultValue={category.sort_order} onBlur={(event) => Number(event.target.value) !== category.sort_order && void save(category, { sort_order: Number(event.target.value) || 0 })} /><span className="rounded-xl bg-slate-100 px-3 py-2 text-sm font-bold text-slate-600">/{category.slug}</span><Button variant="outline" disabled={saving === category.id} onClick={() => void save(category, { active: !category.active })}>{category.active ? "Masquer" : "Afficher"}</Button></article>)}</div></section>; }

function TeamPanel({ team, currentUserId, onRefresh }: { team: Collaborator[]; currentUserId: string; onRefresh: () => Promise<void> }) { const [form, setForm] = useState({ email: "", displayName: "", role: "catalog_manager" as Exclude<CollaboratorRole, "owner"> }); const [pending, setPending] = useState(false); const invite = async () => { setPending(true); const { data, error } = await supabase.functions.invoke("invite-collaborator", { body: form }); setPending(false); if (error) { toast.error(error.message); return; } if (data?.error) { toast.error(data.error); return; } toast.success(data?.message || "Invitation envoyée."); setForm({ email: "", displayName: "", role: "catalog_manager" }); await onRefresh(); }; const update = async (member: Collaborator, changes: Partial<Collaborator>) => { const { error } = await supabase.from("innovtech_admins").update(changes).eq("user_id", member.user_id); if (error) toast.error(error.message); else { toast.success("Collaborateur mis à jour."); await onRefresh(); } }; return <section className="mt-8"><div><p className="eyebrow">Accès sécurisé</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#081A3C]">Collaborateurs et rôles</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">L’invitation est envoyée par e-mail depuis Supabase. Le collaborateur choisit son propre mot de passe ; aucun mot de passe n’est visible ou créé dans ce tableau de bord.</p></div><article className="mt-5 rounded-3xl bg-[#081A3C] p-5 text-white shadow-[0_18px_44px_rgba(8,26,60,.18)] sm:p-7"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-white/10 text-cyan-300"><UserPlus className="h-5 w-5" /></span><div><h3 className="font-display text-xl font-bold">Inviter un collaborateur</h3><p className="text-sm text-blue-100/75">Attribuez un rôle minimal et réversible.</p></div></div><div className="mt-5 grid gap-3 sm:grid-cols-3"><label className="grid gap-2 text-sm font-bold text-blue-50">E-mail<Input className="border-white/20 bg-white text-slate-900" type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} /></label><label className="grid gap-2 text-sm font-bold text-blue-50">Nom affiché (facultatif)<Input className="border-white/20 bg-white text-slate-900" value={form.displayName} onChange={(event) => setForm({ ...form, displayName: event.target.value })} /></label><label className="grid gap-2 text-sm font-bold text-blue-50">Rôle<select className="h-10 rounded-xl border border-white/20 bg-white px-3 text-sm font-bold text-slate-900" value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value as Exclude<CollaboratorRole, "owner"> })}><option value="catalog_manager">Gestionnaire catalogue</option><option value="sales">Commercial</option><option value="viewer">Lecteur</option></select></label></div><Button className="mt-5 bg-[#1FAF62] hover:bg-[#168b4c]" disabled={pending} onClick={() => void invite()}>{pending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <UserPlus className="mr-2 h-4 w-4" />}Envoyer l’invitation</Button></article><div className="mt-5 grid gap-3">{team.map((member) => <article key={member.user_id} className="flex flex-col gap-4 rounded-2xl border border-slate-100 bg-white p-4 shadow-sm sm:flex-row sm:items-center sm:justify-between"><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h3 className="truncate font-display text-lg font-bold text-[#081A3C]">{member.display_name || member.email}</h3><span className={`rounded-full px-2.5 py-1 text-xs font-extrabold ${member.active ? "bg-green-100 text-green-800" : "bg-slate-100 text-slate-600"}`}>{member.active ? "Actif" : "Accès révoqué"}</span></div><p className="mt-1 text-sm text-slate-500">{member.display_name ? member.email : ""} · {roleLabels[member.role]}</p></div><div className="grid gap-2 sm:grid-cols-2"><select aria-label={`Rôle de ${member.email}`} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm font-bold text-slate-700" disabled={member.role === "owner"} value={member.role} onChange={(event) => void update(member, { role: event.target.value as CollaboratorRole })}><option value="owner">Propriétaire</option><option value="catalog_manager">Gestionnaire catalogue</option><option value="sales">Commercial</option><option value="viewer">Lecteur</option></select><Button variant="outline" disabled={member.user_id === currentUserId || member.role === "owner"} onClick={() => void update(member, { active: !member.active })}>{member.active ? "Révoquer" : "Réactiver"}</Button></div></article>)}</div></section>; }

function SettingsPanel({ commercial, hero, onCommercialChange, onHeroChange, pending, onSave }: { commercial: CommercialSettings; hero: HeroSettings; onCommercialChange: (value: CommercialSettings) => void; onHeroChange: (value: HeroSettings) => void; pending: boolean; onSave: () => void }) { const setCommercial = <K extends keyof CommercialSettings>(key: K, value: CommercialSettings[K]) => onCommercialChange({ ...commercial, [key]: value }); const setHero = <K extends keyof HeroSettings>(key: K, value: HeroSettings[K]) => onHeroChange({ ...hero, [key]: value }); return <section className="mt-8"><div><p className="eyebrow">Diffusion publique</p><h2 className="mt-2 font-display text-2xl font-bold tracking-[-.04em] text-[#081A3C]">Réglages commerciaux et accueil</h2><p className="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Ces informations sont enregistrées dans Supabase puis utilisées par le site public. Les textes sont distincts en français et en anglais.</p></div><div className="mt-5 grid gap-5 xl:grid-cols-2"><article className="rounded-3xl border border-blue-100 bg-white p-5 shadow-sm sm:p-7"><div className="flex items-center gap-3"><Settings2 className="h-5 w-5 text-blue-700" /><h3 className="font-display text-xl font-bold text-[#081A3C]">Commerce et WhatsApp</h3></div><div className="mt-5 grid gap-4"><Field label="Numéro WhatsApp (chiffres internationaux)" value={commercial.whatsappNumber} onChange={(value) => setCommercial("whatsappNumber", value.replace(/\D/g, ""))} /><label className="grid gap-2 text-sm font-bold text-slate-700">Message de commande FR<small className="font-medium text-slate-500">Utilisez {"{produit}"} pour insérer le nom du produit.</small><Textarea rows={3} value={commercial.orderMessageFr} onChange={(event) => setCommercial("orderMessageFr", event.target.value)} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Message de commande EN<small className="font-medium text-slate-500">Utilisez {"{product}"} pour insérer le nom du produit.</small><Textarea rows={3} value={commercial.orderMessageEn} onChange={(event) => setCommercial("orderMessageEn", event.target.value)} /></label><Field label="Délai de réponse FR" value={commercial.responseTimeFr} onChange={(value) => setCommercial("responseTimeFr", value)} /><Field label="Délai de réponse EN" value={commercial.responseTimeEn} onChange={(value) => setCommercial("responseTimeEn", value)} /><label className="grid gap-2 text-sm font-bold text-slate-700">Livraison FR<Textarea rows={2} value={commercial.deliveryInfoFr} onChange={(event) => setCommercial("deliveryInfoFr", event.target.value)} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Livraison EN<Textarea rows={2} value={commercial.deliveryInfoEn} onChange={(event) => setCommercial("deliveryInfoEn", event.target.value)} /></label></div></article><article className="rounded-3xl border border-blue-100 bg-white p-5 shadow-sm sm:p-7"><div className="flex items-center gap-3"><ImagePlus className="h-5 w-5 text-blue-700" /><h3 className="font-display text-xl font-bold text-[#081A3C]">Bannière d’accueil</h3></div><div className="mt-5 grid gap-4"><Field label="Surtitre FR" value={hero.eyebrowFr} onChange={(value) => setHero("eyebrowFr", value)} /><Field label="Surtitre EN" value={hero.eyebrowEn} onChange={(value) => setHero("eyebrowEn", value)} /><label className="grid gap-2 text-sm font-bold text-slate-700">Titre FR<Textarea rows={2} value={hero.titleFr} onChange={(event) => setHero("titleFr", event.target.value)} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Titre EN<Textarea rows={2} value={hero.titleEn} onChange={(event) => setHero("titleEn", event.target.value)} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Texte FR<Textarea rows={3} value={hero.bodyFr} onChange={(event) => setHero("bodyFr", event.target.value)} /></label><label className="grid gap-2 text-sm font-bold text-slate-700">Texte EN<Textarea rows={3} value={hero.bodyEn} onChange={(event) => setHero("bodyEn", event.target.value)} /></label><Field label="Bouton FR" value={hero.primaryCtaFr} onChange={(value) => setHero("primaryCtaFr", value)} /><Field label="Bouton EN" value={hero.primaryCtaEn} onChange={(value) => setHero("primaryCtaEn", value)} /><Field label="Lien du bouton" value={hero.primaryHref} onChange={(value) => setHero("primaryHref", value)} placeholder="/boutique" /></div></article></div><div className="mt-6 flex justify-end"><Button size="lg" disabled={pending} onClick={onSave}>{pending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : <Save className="mr-2 h-4 w-4" />}Enregistrer les réglages</Button></div></section>; }
function Field({ label, value, onChange, placeholder = "" }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) { return <label className="grid gap-2 text-sm font-bold text-slate-700">{label}<Input value={value} placeholder={placeholder} onChange={(event) => onChange(event.target.value)} /></label>; }
